package com.yuegang.zhihui.knowledge.application;import com.yuegang.zhihui.knowledge.security.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)class KnowledgeConfiguration{@Bean KnowledgeDocumentService knowledgeDocumentService(DataSource d,@Value("${ygh.knowledge.storage-root}")String r){return new KnowledgeDocumentService(d,r);}@Bean KnowledgeUserResolver knowledgeUserResolver(@Value("${YGH_INTERNAL_REQUEST_HMAC_BASE64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new KnowledgeUserResolver(k);}finally{Arrays.fill(k,(byte)0);}}}
